package com.dawnrise.school.announcement;
import com.dawnrise.school.school.provisioning.*;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class NotificationRecipientAccess {private final RestClient client;private final IdentityProvisioningProperties properties;public NotificationRecipientAccess(@Qualifier("identityProvisioningRestClient")RestClient client,IdentityProvisioningProperties properties){this.client=client;this.properties=properties;}public boolean allowed(long org,long user,String type,long ref){Response r=client.get().uri(b->b.path("/internal/v1/notification-recipients/has-action").queryParam("organizationId",org).queryParam("userId",user).queryParam("actionType",type).queryParam("referenceId",ref).build()).headers(h->{h.set("X-Internal-Api-Key",properties.getApiKey());h.set("X-Service-Name",properties.getServiceName());}).retrieve().body(Response.class);return r!=null&&r.allowed();}record Response(boolean allowed){}}
